def choose_boot(order, disks):
    for name in order:
        if disks.get(name, False):
            return name
    return "No bootable device"

unitTests:
@test("the first bootable disk wins")
def _():
    check_eq(choose_boot(["USB", "SSD"], {"SSD": True}), "SSD")
    check_eq(choose_boot(["USB", "SSD"], {"USB": False, "SSD": True}), "SSD")
    check_eq(choose_boot(["USB", "SSD"], {"USB": True, "SSD": True}), "USB")

@test("nothing to boot")
def _():
    check_eq(choose_boot(["USB", "SSD"], {"SSD": False}), "No bootable device")
    check_eq(choose_boot([], {"SSD": True}), "No bootable device")

